___CSS_LOADER_EXPORT___.push([module.id, "\n.bi-chat-left[data-v-0d7611e0] {\n  text-align: center;\n  position: relative;\n  z-index: 9;\n}\n@media screen and (max-width: 992px) {\n.card[data-v-0d7611e0] {\n    position: fixed;\n    bottom: 0;\n    left: 0;\n    width: 100%;\n    transform: translateY(100%);\n    transition: transform ease-in-out 300ms;\n    z-index: 9;\n}\nla-gutter-item[active][data-v-0d7611e0] {\n    z-index: 9;\n}\nla-gutter-item[active] .card[data-v-0d7611e0] {\n    transform: translateY(0);\n}\n}\n", "",{"version":3,"sources":["webpack://./peachjam/js/components/RelationshipEnrichment/RelationshipEnrichment.vue"],"names":[],"mappings":";AAgLA;EACE,kBAAkB;EAClB,kBAAkB;EAClB,UAAU;AACZ;AAEA;AACE;IACE,eAAe;IACf,SAAS;IACT,OAAO;IACP,WAAW;IACX,2BAA2B;IAC3B,uCAAuC;IACvC,UAAU;AACZ;AAEA;IACE,UAAU;AACZ;AAEA;IACE,wBAAwB;AAC1B;AACF","sourcesContent":["<template>\n  <la-gutter-item\n    class=\"relationship-gutter-item\"\n    :anchor.prop=\"anchorElement\"\n  >\n    <i\n      class=\"bi bi-chat mobile-gutter-item-icon\"\n      role=\"button\"\n      @click=\"activate\"\n    />\n    <div class=\"card gutter-item-card\">\n      <div class=\"card-body\">\n        <div class=\"mb-2 d-lg-none text-end\">\n          <button\n            type=\"button\"\n            class=\"btn-close\"\n            aria-label=\"Close\"\n            @click.stop=\"deactivate\"\n          />\n        </div>\n\n        <div\n          v-if=\"editable\"\n          class=\"float-end d-none d-lg-block\"\n        >\n          <div class=\"dropdown\">\n            <a\n              class=\"dropdown-toggle\"\n              href=\"#\"\n              data-bs-toggle=\"dropdown\"\n            />\n            <ul class=\"dropdown-menu\">\n              <li>\n                <a\n                  class=\"dropdown-item\"\n                  href=\"#\"\n                  @click.prevent=\"remove\"\n                >\n                  {{ $t('Delete') }}\n                </a>\n              </li>\n            </ul>\n          </div>\n        </div>\n\n        <div v-if=\"isForwards\">\n          {{ $t('This provision') }}\n          {{ enrichment.predicate.verb }}\n          <a\n            v-if=\"objectDocument\"\n            target=\"_blank\"\n            :href=\"`${objectDocument.expression_frbr_uri}/`\"\n          >{{ objectDocument.title }}</a><span v-else>{{ enrichment.object_work.frbr_uri }}</span>.\n        </div>\n        <div v-else>\n          <a\n            v-if=\"subjectDocument\"\n            target=\"_blank\"\n            :href=\"`${subjectDocument.expression_frbr_uri}/`\"\n          >{{ subjectDocument.title }}</a><span v-else>{{ enrichment.subject_work.frbr_uri }}</span>.\n          {{ $t('{reverse_verb} this provision', { reverse_verb: enrichment.predicate.reverse_verb }) }}.\n        </div>\n      </div>\n    </div>\n  </la-gutter-item>\n</template>\n\n<script>\nimport { markRange, targetToRange } from '@lawsafrica/indigo-akn/dist/ranges';\nimport { bestDocument } from './enrichment';\n\nexport default {\n  name: 'RelationshipEnrichment',\n  props: {\n    enrichment: {\n      type: Object,\n      default: null\n    },\n    viewRoot: HTMLElement,\n    gutter: HTMLElement,\n    editable: Boolean,\n    useSelectors: Boolean,\n    thisWorkFrbrUri: {\n      type: String,\n      default: ''\n    }\n  },\n  emits: ['delete'],\n  data: () => ({\n    marks: [],\n    anchorElement: null\n  }),\n\n  computed: {\n    isForwards () {\n      return this.enrichment.subject_work.frbr_uri === this.thisWorkFrbrUri;\n    },\n\n    objectDocument () {\n      return bestDocument(this.enrichment.object_documents, 'eng');\n    },\n\n    subjectDocument () {\n      return bestDocument(this.enrichment.subject_documents, 'eng');\n    }\n  },\n\n  mounted () {\n    this.markAndAnchor();\n    window.addEventListener('click', this.handleOutsideClick);\n    // this can't be attached with vue's normal event listener because of the naming\n    this.$el.addEventListener('laItemChanged', this.itemChanged);\n\n    this.gutter.appendChild(this.$el);\n  },\n\n  unmounted () {\n    this.unmark();\n  },\n\n  methods: {\n    itemChanged () {\n      // either the active or anchor state has changed\n      if (this.$el.active) {\n        this.activate();\n      } else {\n        this.deactivate();\n      }\n    },\n    deactivate () {\n      this.$el.active = false;\n      this.marks.forEach(mark => mark.classList.remove('active'));\n    },\n    activate () {\n      this.$el.active = true;\n      this.marks.forEach(mark => mark.classList.add('active'));\n    },\n    markAndAnchor () {\n      this.unmark();\n      const target = {\n        anchor_id: this.isForwards ? this.enrichment.subject_target_id : this.enrichment.object_target_id,\n        selectors: this.useSelectors ? (\n          this.isForwards ? this.enrichment.subject_selectors : this.enrichment.target_selectors\n        ) : null\n      };\n      const range = targetToRange(target, this.viewRoot);\n      if (!range) return;\n      markRange(range, 'mark', mark => {\n        this.marks.push(mark);\n        mark.classList.add('enrich', 'enrich-relationship');\n        mark.addEventListener('click', this.activate);\n        return mark;\n      });\n      this.anchorElement = this.marks[0];\n    },\n\n    unmark () {\n      this.marks.forEach(mark => {\n        const parent = mark.parentNode;\n        while (mark.firstChild) parent.insertBefore(mark.firstChild, mark);\n        parent.removeChild(mark);\n      });\n      this.marks = [];\n    },\n\n    remove () {\n      if (confirm('Are you sure?')) {\n        this.$emit('delete', this.enrichment);\n      }\n    }\n  }\n};\n</script>\n\n<style scoped>\n\n.bi-chat-left {\n  text-align: center;\n  position: relative;\n  z-index: 9;\n}\n\n@media screen and (max-width: 992px) {\n  .card {\n    position: fixed;\n    bottom: 0;\n    left: 0;\n    width: 100%;\n    transform: translateY(100%);\n    transition: transform ease-in-out 300ms;\n    z-index: 9;\n  }\n\n  la-gutter-item[active] {\n    z-index: 9;\n  }\n\n  la-gutter-item[active] .card {\n    transform: translateY(0);\n  }\n}\n</style>\n"],"sourceRoot":""}]);
